import pathlib,json,hashlib,base64,datetime
root=pathlib.Path('/home/orionh/HEXAPOD_runs/mkii_profile_v1/profile_001')
files={}
for name in ['supervisor.json', 'validation_report.json', 'container.stdout.log', 'container.stderr.log', 'admitted', 'cpu_asset_audit.json']:
 p=root/name
 before=p.stat()
 data=p.read_bytes()
 after=p.stat()
 if (before.st_size,before.st_mtime_ns)!=(after.st_size,after.st_mtime_ns): raise RuntimeError('Remote file changed during read: '+name)
 files[name]={'size_bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),'mtime_ns':after.st_mtime_ns,'base64':base64.b64encode(data).decode('ascii')}
traces={}
for p in sorted(root.glob('*trace*')):
 if p.is_file():
  before=p.stat(); h=hashlib.sha256()
  with p.open('rb') as f:
   for block in iter(lambda:f.read(1024*1024),b''): h.update(block)
  after=p.stat()
  if (before.st_size,before.st_mtime_ns)!=(after.st_size,after.st_mtime_ns): raise RuntimeError('Trace changed during hash')
  traces[p.name]={'remote_path':str(p),'size_bytes':after.st_size,'sha256':h.hexdigest(),'mtime_ns':after.st_mtime_ns,'copied':False}
print(json.dumps({'remote_root':str(root),'captured_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':files,'remote_only_traces':traces}))
